	}
}
EOF
cp /work/resources/Purchase.json resources/Purchase.json
sed -i 's#"fetch": \["127.0.0.1:18090"\]#"fetch": []#; s#"/purchases"#"/purchases"#' resources/Purchase.json
cat > resources/purchase.query.ts <<'EOF'
export default function query(ctx: QueryContext): Sql {
  return ctx.sql`SELECT p.id, p.created_at AS "createdAt", p.total_cents AS "totalCents",
    (SELECT coalesce(json_agg(json_build_object('bookId', l.book_id, 'title', b.title, 'quantity', l.quantity,
        'unitPriceCents', l.unit_price_cents) ORDER BY l.id), '[]')
       FROM purchase_line l JOIN book b ON b.id = l.book_id WHERE l.purchase_id = p.id) AS lines
    FROM purchase p
    WHERE p.customer_id = ${ctx.get("customer")}`;
}
EOF
cat > resources/customer.handler.ts <<'EOF'
export default function customer(id: number, ctx) {
  ctx.set("customer", id);
  return null;
}
EOF
cat > resources/purchase.command.ts <<'EOF'
export function create(input, ctx) {
  const customer = ctx.get("customer");
  const books = {};
  const bookIds = [];
  for (let i = 0; i < input.lines.length; i++) {
    const line = input.lines[i];
    if (books[line.bookId] === undefined) {
      const [book] = ctx.db.query(ctx.sql`SELECT id, price_cents AS "priceCents", stock FROM book
        WHERE id = ${line.bookId} AND published FOR UPDATE`);
      if (!book) ctx.reject({ message: `book ${line.bookId} is not available`, pointer: `/lines/${i}/bookId`, status: 422 });
      books[line.bookId] = { priceCents: book.priceCents, stock: book.stock, wanted: 0 };
      bookIds.push(line.bookId);
    }
    books[line.bookId].wanted += line.quantity;
  }
  for (const bookId of bookIds) {
    if (books[bookId].wanted > books[bookId].stock) {
      ctx.reject({ message: `not enough stock for book ${bookId}`, code: "insufficient_stock", status: 409 });
    }
  }
  let totalCents = 0;
  for (const line of input.lines) totalCents += line.quantity * books[line.bookId].priceCents;
  const [purchase] = ctx.db.query(ctx.sql`INSERT INTO purchase (customer_id, created_at, total_cents)
    VALUES (${customer}, now(), ${totalCents}) RETURNING id`);
  for (const line of input.lines) {
    ctx.db.exec(ctx.sql`INSERT INTO purchase_line (purchase_id, book_id, quantity, unit_price_cents)
      VALUES (${purchase.id}, ${line.bookId}, ${line.quantity}, ${books[line.bookId].priceCents})`);
  }
  for (const bookId of bookIds) {
    ctx.db.exec(ctx.sql`UPDATE book SET stock = stock - ${books[bookId].wanted} WHERE id = ${bookId}`);
  }
  const [check] = ctx.db.query(ctx.sql`SELECT p.total_cents AS t, (SELECT count(*) FROM purchase_line WHERE purchase_id = p.id) AS n FROM purchase p WHERE p.id = ${purchase.id}`);
  ctx.reject({ message: `ROLLBACK-OK purchase=${purchase.id} total=${check.t} lines=${check.n}`, code: "rollback_test", status: 418 });
}
EOF
